INSERT INTO processo_juridico (numero_processo_cnj, area_juridica, estado, comarca, juizo, data_distribuicao, advogado_do_caso, fase, risco, autor, cpf_autor, cnpj, cliente, advogado_adverso, valor_da_causa, execucao, acordo, resumo_dos_fatos, funcao, andamento_relatorio, previsao_de_pagamento, data_acordo) VALUES ('9146155-78.2020.8.8.19.5893', 'Direito Tributário', 'RJ', 'Angra dos Reis', '5ª Vara Cível de Duque de Caxias', '2025-05-15', 'Dra. Aline Gomes (OAB/GO 012.345)', 'Sentença', 'ALTO', 'Felipe Santos Araújo', '338.565.492-00', NULL, 'Fábrica de Móveis Estilo', 'Dr. Gustavo Alves (OAB/CE 901.234)', 271591.12, 27167.28, 222119.28, 'Ação de cobrança de aluguéis e encargos em atraso. Inquilino encontra-se inadimplente há 23 meses. Valor atribuído à causa considera danos materiais e morais sofridos pelo requerente.', 'Gerente', 'Perícia deferida pelo juízo. Aguardando nomeação de perito para início dos trabalhos técnicos.', '2025-10-08', '2025-07-06');
INSERT INTO processo_juridico (numero_processo_cnj, area_juridica, estado, comarca, juizo, data_distribuicao, advogado_do_caso, fase, risco, autor, cnpj, cpf_autor, cliente, advogado_adverso, valor_da_causa, execucao, resumo_dos_fatos, funcao) VALUES ('8451530-52.2020.8.8.26.8665', 'Direito Previdenciário', 'MS', 'Dourados', '1ª Vara do Trabalho de Campo Grande', '2025-06-04', 'Dr. Felipe Martins (OAB/AM 123.987)', 'Instrução', 'BAIXO', 'Escola Particular Saber', '04.122.075/8026-93', NULL, 'Empresa de TI Soluções Digitais', 'Dr. Fernando Costa (OAB/MG 345.678)', 76017.72, 30872.34, 'Ação de indenização por danos materiais e morais decorrentes de acidente de trânsito. Colisão causou danos significativos ao veículo. Caso não seja possível acordo, pugna-se pela citação da requerida para contestar sob pena de revelia.', 'Vendedor');
